// stub DOM: 1 red H1 (no border), 3 divs on white bg (no border), 1 rule with a real border
const els = [
  { color:'rgb(255, 0, 0)', backgroundColor:'rgba(0, 0, 0, 0)', borderTopColor:'rgb(255, 0, 0)', borderTopWidth:'0px' },
  { color:'rgb(17, 17, 17)', backgroundColor:'rgb(255, 255, 255)', borderTopColor:'rgb(17, 17, 17)', borderTopWidth:'0px' },
  { color:'rgb(17, 17, 17)', backgroundColor:'rgb(255, 255, 255)', borderTopColor:'rgb(17, 17, 17)', borderTopWidth:'0px' },
  { color:'rgb(17, 17, 17)', backgroundColor:'rgb(255, 255, 255)', borderTopColor:'rgb(17, 17, 17)', borderTopWidth:'0px' },
  { color:'rgb(17, 17, 17)', backgroundColor:'rgba(0, 0, 0, 0)', borderTopColor:'rgb(234, 234, 234)', borderTopWidth:'1px' },
];
global.document = { querySelectorAll: () => els };
global.getComputedStyle = e => e;

// --- shipped query, pasted verbatim from REDESIGN.md ---
const out =
Object.entries([...document.querySelectorAll('*')].flatMap(e => { const s = getComputedStyle(e);
  return [s.color, s.backgroundColor,
          parseFloat(s.borderTopWidth) > 0 ? s.borderTopColor : null]; })
  .filter(v => v && v !== 'rgba(0, 0, 0, 0)')
  .reduce((m, v) => (m[v] = (m[v] || 0) + 1, m), {}))
  .sort((a, b) => b[1] - a[1]);

console.log(out);
const assert = require('assert');
assert.deepStrictEqual(out[0], ['rgb(17, 17, 17)', 4], 'ranked: most-used first');
assert.deepStrictEqual(out[1], ['rgb(255, 255, 255)', 3], 'background not buried');
assert.deepStrictEqual(out.find(([v]) => v === 'rgb(255, 0, 0)'), ['rgb(255, 0, 0)', 1], 'no border double-count');
assert.ok(out.find(([v]) => v === 'rgb(234, 234, 234)'), 'real border color still counted');
assert.ok(out.every(([, n], i) => i === 0 || n <= out[i-1][1]), 'sorted desc');
console.log('OK: no double-count, real border kept, ranked descending');
